DECLARE @FromDate SMALLDATETIME = '20230701'
DECLARE @ToDate SMALLDATETIME = '20230901'
DECLARE @rowcount INT = 0

WHILE (@FromDate <= @ToDate)
BEGIN
	
	INSERT INTO ExchangeDailyOanda ([ExchangeDate], [ExchangeId], [Code], [MYR], [USD], [EUR], [CNY], [ActualRate], [IDR], [AUD], [CHF], [GBP], [SGD], [THB], [VND], [KRW], [JPY], [HKD], [TWD], [PHP], [BDT], [INR])
	SELECT @FromDate, a.[ExchangeId], a.[Code], a.[MYR], a.[USD], a.[EUR], a.[CNY], a.[ActualRate], a.[IDR], a.[AUD], a.[CHF], a.[GBP], a.[SGD], a.[THB], a.[VND], a.[KRW], a.[JPY], a.[HKD], a.[TWD], a.[PHP], a.[BDT], a.[INR]
	FROM #ExchangeDailyOanda a LEFT JOIN ExchangeDailyOanda b WITH(NOLOCK) 
		ON @FromDate = b.ExchangeDate AND a.ExchangeId = b.ExchangeId
	WHERE b.ExchangeDate IS NULL 
	SET @rowcount = @@ROWCOUNT
	PRINT 'Done - ' + CONVERT (VARCHAR(20),@FromDate,105) +' - ' + CONVERT (VARCHAR(10),@rowcount) + ' rows affected' 
	SET @FromDate = DATEADD(DAY,1,@FromDate)

END
GO
